using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;
namespace CircuitoStudio {
public sealed class NetworkFlowForm:Form {
Project project;Circuit circuit;NetworkFlowSettings settings;NetworkFlowLoad load;List<Action> readers=new List<Action>();DataGridView grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells};TextBox details=new TextBox{Dock=DockStyle.Bottom,Height=230,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};public bool Changed{get;private set;}
public NetworkFlowForm(Project p,Circuit c){project=p;circuit=c;settings=p.FlowSettings==null?new NetworkFlowSettings{NominalLineVoltageV=p.Source.LineVoltage,FrequencyHz=p.Frequency}:p.FlowSettings.Copy();load=c==null||c.ChildBoardId!=""?null:c.FlowLoad==null?new NetworkFlowLoad():c.FlowLoad.Copy();Text="Fluxo por fase e neutro"+(c==null?"":" — "+c.Id);Size=new Size(1500,930);MinimumSize=new Size(1180,740);Font=new Font("Segoe UI",10);var split=new SplitContainer{Dock=DockStyle.Fill};split.Size=new Size(1440,800);split.SplitterDistance=540;var tabs=new TabControl{Dock=DockStyle.Fill};var source=new TabPage("Fonte permanente / método");source.Controls.Add(TypedFields.Create(settings,readers));var terminal=new TabPage("Carga selecionada");if(load!=null)terminal.Controls.Add(TypedFields.Create(load,readers));else terminal.Controls.Add(new Label{Text="Selecione carga terminal para declarar ligação e modelo; alimentadores usam os circuitos a jusante.",Dock=DockStyle.Fill});tabs.TabPages.AddRange(new[]{source,terminal});split.Panel1.Controls.Add(tabs);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=90};Add(bar,"Calcular cópia",()=>EvaluateDraft(false));Add(bar,"Salvar configuração",()=>EvaluateDraft(true));Add(bar,"Exportar CSV salvo",Export);Add(bar,"Remover modelo da carga",()=>{if(circuit==null)throw new InvalidDataException("Selecione um circuito.");circuit.FlowLoad=null;Changed=true;details.Text="Modelo da carga removido; fluxo ficará pendente até definir os dados necessários.";});Add(bar,"Desativar perfil global",()=>{project.FlowSettings=null;Changed=true;grid.Rows.Clear();details.Text="Perfil global removido. Opções de carga são preservadas; sem perfil, não há solução de fluxo aceita.";});split.Panel2.Controls.Add(grid);split.Panel2.Controls.Add(details);split.Panel2.Controls.Add(bar);Controls.Add(split);foreach(var col in new[]{"Circuito","Ligação V","V1 (V)","V2 (V)","V3 (V)","I1 fund (A)","I2 fund (A)","I3 fund (A)","IN fund (A)","|queda| %","Min PU","Perda W"})grid.Columns.Add(col,col);details.Text="Declare fonte permanente/impedâncias, modelo de neutro e ligação/modelo de cada carga. Curto/Xd inicial não é preenchimento automático da fonte de regime. Cargas PQ ou impedância, correntes fundamentais; neutro ideal exige hipótese explícita. Todas as raízes compartilham uma fonte; demanda aplicada uma vez por carga terminal. Sem convergência não mostrar última aproximação como resultado aceito. Dados vazios ficam pendentes; zero é ideal declarado nas impedâncias nullable.";}
void Add(Control parent,string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=32};b.Click+=(s,e)=>{try{action();}catch(Exception ex){grid.Rows.Clear();details.Text="Nenhuma alteração: "+ex.Message;}};parent.Controls.Add(b);}
public NetworkFlowResult EvaluateDraft(bool commit){foreach(var reader in readers)reader();settings.Validate();if(load!=null)load.Validate();var oldSettings=project.FlowSettings;var oldLoad=circuit==null?null:circuit.FlowLoad;project.FlowSettings=settings.Copy();if(circuit!=null&&circuit.ChildBoardId=="")circuit.FlowLoad=load.Copy();bool saved=false;try{project.Validate();var result=NetworkFlow.Run(project);grid.Rows.Clear();foreach(var row in result.Circuits)grid.Rows.Add(row.Circuit.Id,row.VoltageMeaning,row.OperatingVoltagesV[0].ToString("N4"),row.OperatingVoltagesV.Length>1?row.OperatingVoltagesV[1].ToString("N4"):"",row.OperatingVoltagesV.Length>2?row.OperatingVoltagesV[2].ToString("N4"):"",row.Current[0].Magnitude.ToString("N4"),row.Current[1].Magnitude.ToString("N4"),row.Current[2].Magnitude.ToString("N4"),row.NeutralCurrentA.ToString("N4"),row.MaximumAbsDropPercent.ToString("N4"),row.MinimumVoltagePu.ToString("N6"),row.LossVA.Real.ToString("N4"));details.Text=result.Status+"\r\n"+result.Detail;if(commit){saved=true;Changed=true;}return result;}finally{if(!saved){project.FlowSettings=oldSettings;if(circuit!=null)circuit.FlowLoad=oldLoad;}}}
void Export(){using(var d=new SaveFileDialog{Filter="Fluxo CSV|*.csv",FileName="fluxo-por-fase.csv"})if(d.ShowDialog(this)==DialogResult.OK)NetworkFlow.Export(project,d.FileName);}
}
partial class Studio {void ConfigureNetworkFlow(){using(var form=new NetworkFlowForm(project,circuit)){form.ShowDialog(this);if(form.Changed)Change();}}}
}
